#!/usr/bin/env bash
# =====================================================================================
# Polaris² (Schedule Forensics) — one-file installer (Tier 1 - 16 GB RAM, no discrete GPU) — Linux
# =====================================================================================
# Generated by tools/installer/build_installers.py — DO NOT hand-edit below the CONFIG
# block; regenerate instead. Bash 4+; needs: python3 (3.11+), base64, and curl or wget
# (for the MPXJ converter, and only if installing Ollama).
#
# What this does (checking before installing — nothing already present is reinstalled):
#   1. Verifies machine fit (RAM / GPU) for this tier — warns, never blocks.
#   2. Verifies Python 3.11+ (tells you the distro package to install if missing).
#   3. Installs the tool into its OWN venv from the wheel EMBEDDED in this file
#      (no internet needed for the tool itself).
#   3b. Deploys the MPXJ converter that native .mpp import needs — copied from a repo
#      checkout beside this file if there is one, else downloaded (~17 MB) and SHA-256
#      verified against the manifest baked into this installer.
#   4. Optionally installs Ollama + this tier's local AI model (skippable — the tool
#      runs fully without AI).
#   5. Creates Start/Stop launchers (~/.local/bin + desktop entries), an uninstaller,
#      and a first-run README.
#
# DATA SOVEREIGNTY: the installed tool binds 127.0.0.1 only — schedule data never
# leaves the machine. Internet is used ONLY at install time for public prerequisites.
# Set SF_MPXJ_OFFLINE=1 to suppress the MPXJ download on an air-gapped machine.
#
# Run:            bash install-tier1.sh
# Non-interactive smoke test (skips AI, temp root):  SF_INSTALLER_SMOKE=1 bash install-tier1.sh
# =====================================================================================

# ------------------------------- TIER CONFIG (edit freely) --------------------------
# Defaults chosen 2026-07-02 per INSTALLER-SPEC.md SS3 (operator authorized autonomous build;
# edit these five lines freely - they are the ONLY tier-specific values in this file).
TIER_LABEL="Tier 1 - 16 GB RAM, no discrete GPU"
MIN_RAM_GB=16
NEEDS_GPU=false
OLLAMA_MODEL="llama3.2:3b"
MODEL_DISK_GB=2
# ---------------------------- END TIER CONFIG — SHARED BODY -------------------------

set -euo pipefail
SMOKE="${SF_INSTALLER_SMOKE:-0}"
if [ "$SMOKE" = "1" ]; then
  INSTALL_ROOT="${SF_INSTALL_ROOT:-$(mktemp -d)/ScheduleForensics}"
else
  INSTALL_ROOT="${SF_INSTALL_ROOT:-$HOME/.local/share/ScheduleForensics}"
fi
VENV_DIR="$INSTALL_ROOT/venv"
APP_PORT=8321
mkdir -p "$INSTALL_ROOT"

step() { printf '\n\033[36m==> %s\033[0m\n' "$1"; }
ok()   { printf '    \033[32m[ok]\033[0m %s\n' "$1"; }
warn() { printf '    \033[33m[!!]\033[0m %s\n' "$1"; }

echo ""
echo "Polaris² (Schedule Forensics) installer — v1.0.289 — ${TIER_LABEL}"
echo "This file embeds and installs exactly v1.0.289. For a newer release, re-download the latest installer — an old file reinstalls its old version."
echo "Install location: $INSTALL_ROOT"

# --- 1. machine fit (warn-only) ------------------------------------------------------
step "Checking machine fit for this tier"
ram_gb=$(( $(grep MemTotal /proc/meminfo | awk '{print $2}') / 1024 / 1024 ))
if [ "$ram_gb" -lt "$MIN_RAM_GB" ]; then
  warn "This machine reports ${ram_gb} GB RAM; this tier targets ${MIN_RAM_GB} GB+. The tool will run; the AI model may be slow or fail to load."
else
  ok "${ram_gb} GB RAM (tier targets ${MIN_RAM_GB} GB+)"
fi
if [ "$NEEDS_GPU" = "true" ]; then
  if command -v nvidia-smi >/dev/null 2>&1 || ls /dev/dri/render* >/dev/null 2>&1; then
    ok "GPU device detected"
  else
    warn "No GPU detected; this tier's AI model expects one (it will run on CPU — slow — or fail to load)."
  fi
fi

# --- 2. Python 3.11+ ------------------------------------------------------------------
step "Checking Python 3.11+"
PY=""
for cand in python3.13 python3.12 python3.11 python3; do
  if command -v "$cand" >/dev/null 2>&1; then
    if "$cand" -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 11) else 1)'; then
      PY="$cand"; break
    fi
  fi
done
if [ -z "$PY" ]; then
  echo "Python 3.11+ not found. Install it with your package manager, e.g.:" >&2
  echo "    sudo apt install python3.12 python3.12-venv     # Debian/Ubuntu" >&2
  echo "    sudo dnf install python3.12                     # Fedora" >&2
  exit 1
fi
ok "Python found: $PY ($($PY -V))"

# --- 3. the tool, into its own venv, from the wheel embedded below --------------------
step "Installing Polaris² into its own environment"
if [ ! -x "$VENV_DIR/bin/python" ]; then
  "$PY" -m venv "$VENV_DIR"
  ok "Created venv"
else
  ok "venv already present (re-using)"
fi
WHEEL_PATH="$INSTALL_ROOT/schedule_forensics-1.0.289-py3-none-any.whl"
# the payload sits between the PAYLOAD markers at the end of this file
awk '/^# ===BEGIN WHEEL_B64===/{flag=1; next} /^# ===END WHEEL_B64===/{flag=0} flag {sub(/^# ?/, ""); print}' "$0" | base64 -d > "$WHEEL_PATH"
"$VENV_DIR/bin/python" -m pip install --quiet --upgrade pip
"$VENV_DIR/bin/python" -m pip install --quiet --force-reinstall "$WHEEL_PATH"
"$VENV_DIR/bin/python" -c "import schedule_forensics" || { echo "The tool failed to import after install." >&2; exit 1; }
ok "Installed schedule_forensics-1.0.289-py3-none-any.whl"
# optional HUD telemetry enhancer — best-effort, never fatal (stdlib collectors cover Linux)
"$VENV_DIR/bin/python" -m pip install --quiet psutil >/dev/null 2>&1 || true

# --- 3b. vendored MPXJ converter (native .mpp support) --------------------------------
# The wheel is pure Python; the ~17 MB Java converter is what makes native .mpp import
# work, and without it EVERY .mpp import fails with "MPXJ runner not found".
#
# ADR-0299: it is not embedded (23 MB of base64 x 9 installers, re-committed on every
# version bump), and it must not depend on a repo checkout either — the documented deploy
# path is a SINGLE downloaded file, where the old `dirname "$0"/..` lookup missed, silently
# left .mpp support OFF, and still printed DONE. So: several layouts are searched, and
# failing those the pinned file set is downloaded and verified byte-for-byte against the
# SHA-256 manifest baked in at build time.
#
# TWO RULES THIS BLOCK MUST NEVER BREAK (both mutation-verified — MPXJ-CAPABILITY-REPORT.md):
#  1. NEVER DESTROY AN INSTALLED CONVERTER. Widening the search makes the already-installed
#     copy selectable as a SOURCE, and the copy step rm -rf's the destination first — so a
#     re-run would delete the operator's only converter. Hence the self-copy skip, and hence
#     the download stages into a temp dir and is swapped in ONLY once every byte verifies.
#     A failed download must leave an existing install exactly as it was.
#  2. REPORT THE CAPABILITY OF THE DEPLOYED TOOL, NOT THE OUTCOME OF THIS COPY STEP. An
#     upgrade that finds no source but already has a converter installed leaves native .mpp
#     ON; saying "stays OFF" there was simply false, and on a testimony tool a false claim
#     about your own capability is a correctness defect. Whatever is printed below must
#     agree with what `importers/mpp_mpxj.py::_mpxj_home` will find.
MPXJ_BASE_URL="https://raw.githubusercontent.com/polittdj/schedule-manipulation-analysis-tool-experiment/163d1942030851cae63bbf6cb50e8ed37795bb5a/tools/mpxj"
# The anonymous raw URL above requires a PUBLIC repository. This one went private (DISC-01
# remediation, 2026-08-13), so the fetch is token-aware: with SF_GITHUB_TOKEN (yours) or
# GITHUB_TOKEN (CI's built-in) set, sf_fetch_mpxj switches to the authenticated GitHub
# contents API at the SAME pinned commit. The SHA-256 manifest check below is identical
# either way — the bytes are proven, not the transport.
MPXJ_API_BASE="https://api.github.com/repos/polittdj/schedule-manipulation-analysis-tool-experiment/contents/tools/mpxj"
MPXJ_REF="163d1942030851cae63bbf6cb50e8ed37795bb5a"
SF_GH_TOKEN="${SF_GITHUB_TOKEN:-${GITHUB_TOKEN:-}}"
MPXJ_MANIFEST="$(cat <<'SF_MPXJ_MANIFEST_EOF'
e114b1641b1b8dfe7c27f01f2ee3b6c44ddedd9dbf40eb79edefcc107a8b9856  MpxjToMspdi.java
db634566a65ad7e1bdd8f609bc45ca65bf902493e1c71c67b4ea9e81f11f14d7  classes/MpxjToMspdi.class
f76b85adb0c00721ae267b7cfde4da7f71d3121cc2160c9fc00c0c89f8c53c8a  lib/SparseBitSet-1.3.jar
6af66595f9f6a7bb58ce66518d6888d40b547c366d2262f06676eee19528ff66  lib/commons-codec-1.20.0.jar
00f93263c267be201b8ae521b44a7137271b16688435340bf629db1bac0a5845  lib/commons-collections4-4.5.0.jar
7d643a2afea8b058b762aa6fb90e5b256f6c729739f8b3784c3370ddc609e88d  lib/commons-io-2.21.0.jar
4eeeae8d20c078abb64b015ec158add383ac581571cddc45c68f0c9ae0230720  lib/commons-lang3-3.18.0.jar
daddea1ea0be0f56978ab3006b8ac92834afeefbd9b7e4e6316fca57df0fa636  lib/commons-logging-1.2.jar
1e56d7b058d28b65abd256b8458e3885b674c1d588fa43cd7d1cbb9c7ef2b308  lib/commons-math3-3.6.1.jar
9f91115f449384886f572bd62c8812ee1004273d4b5c85cac65179ad4c16990f  lib/istack-commons-runtime-4.0.1.jar
adf3f6f513c888f158862b00cf2db51ad6309732105e6de4bfd747670f60a033  lib/jackcess-4.0.10.jar
53ca085f4a150f703f49e1aabd935bd03b43e1ea3d55d135438292af22cef56b  lib/jackson-annotations-2.21.jar
1edd5f2e49dca5f8e4519957c24b7b3050bd1c7ee883920da33cff031ff1f7c0  lib/jackson-core-2.21.1.jar
b011eb5202d9ec889e27f1dcbdf6c63f06a76e7a16c0a1b30c6048d556c9a28e  lib/jackson-databind-2.21.1.jar
b9e24b7dd6e07495562ea96531be3130c96dba4d78e1dfd88adbbdebf4332871  lib/jakarta.activation-2.0.1.jar
b8fb4bee3ff5b5c1ef77144d8411316018d7bbd41fcf1ede0646f7978546b867  lib/jakarta.xml.bind-api-3.0.1.jar
f9a360b939597643b2676e35fc497afb561d20e8a513128a5c0070366db11bbd  lib/jaxb-core-3.0.2.jar
7b3a3784b9c6e343a8d38fc108602ba810177f03f2d8d1e7258b1cef7fd9d4c7  lib/jaxb-runtime-3.0.2.jar
83c4db194424416f1698f2a290f8b09592738dfc5cf5ceb1cc3a5154d2ada256  lib/jgoodies-binding-2.13.0.jar
ddca10c16e1dc7a1b399c14580f0aae23014851e57d224cb96c260e6d649d2ad  lib/jgoodies-common-1.8.1.jar
cfd3298d8720cddfb0545109ccc6ea0ef39eff7e9c40a10ad95c93a65f01c916  lib/jsoup-1.22.1.jar
5b4a0a0cd0e751ded431c162442bdbdd53328d1f8bb2bae5fc1bbeee0f66d80f  lib/log4j-api-2.24.3.jar
b73997d69823a80bb168a5b7b6923450a6897946b3916037d6d6ece782b540cd  lib/mpxj-16.2.0.jar
6c52e876ca75775a11b56e4b36a7541f682827f56406725fcd87560b792ee3d8  lib/poi-5.5.1.jar
aa13625c4a9fc0234caf5e13a6cc3f44ce0d34c5541bb4b1d8ecaf52cb031237  lib/rtfparserkit-1.16.0.jar
b4bcf94fb0a759456e2521724513baec94b78e93127544af162e3cff08d93343  lib/txw2-3.0.2.jar
f80078970a148fda65e4855a48bd5b4540e5a3058f9c7562d0789ed2cb6c8719  setup.ps1
a08844b17f06889397bb4229f79d1ec1de6d4ce1a3bc802d9f6856832d640288  setup.sh
SF_MPXJ_MANIFEST_EOF
)"
MPXJ_DEST="$INSTALL_ROOT/tools/mpxj"
# `pwd -P` — the PHYSICAL path. A logical `pwd` reports the SYMLINK's own spelling, so a
# candidate that is merely a link to the installed copy compared unequal to the destination,
# slipped past the self-copy skip, and the copy step then rm -rf'd the real directory and
# "copied" from the link it had just broken — destroying the converter AND printing
# `[ok] MPXJ converter deployed`. Reproduced end-to-end before this line changed (ADR-0300;
# the symlink case was found by the parallel #449 investigation).
sf_realpath() { (cd "$1" 2>/dev/null && pwd -P) || printf '%s\n' "$1"; }
MPXJ_DEST_REAL="$(sf_realpath "$MPXJ_DEST")"
sf_sha256() {  # coreutils on Linux, shasum on macOS
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | awk '{print $1}'
  else shasum -a 256 "$1" | awk '{print $1}'; fi
}
sf_fetch() {   # $1 = url, $2 = destination
  if command -v curl >/dev/null 2>&1; then curl -fsSL --retry 3 -o "$2" "$1"
  else wget -q -O "$2" "$1"; fi
}

sf_fetch_mpxj() {   # $1 = path relative to tools/mpxj, $2 = destination
  if [ -n "$SF_GH_TOKEN" ]; then
    if command -v curl >/dev/null 2>&1; then
      curl -fsSL --retry 3 -H "Authorization: Bearer $SF_GH_TOKEN" \
        -H "Accept: application/vnd.github.raw+json" -o "$2" "$MPXJ_API_BASE/$1?ref=$MPXJ_REF"
    else
      wget -q --header="Authorization: Bearer $SF_GH_TOKEN" \
        --header="Accept: application/vnd.github.raw+json" -O "$2" "$MPXJ_API_BASE/$1?ref=$MPXJ_REF"
    fi
  else
    sf_fetch "$MPXJ_BASE_URL/$1" "$2"
  fi
}
MPXJ_SRC=""
SF_HERE="$(cd "$(dirname "$0")" 2>/dev/null && pwd || printf '%s\n' ".")"
for cand in "${SF_MPXJ_HOME:-}" "$SF_HERE/../tools/mpxj" "$SF_HERE/tools/mpxj" "$PWD/tools/mpxj"; do
  if [ -z "$cand" ]; then continue; fi
  if [ ! -f "$cand/classes/MpxjToMspdi.class" ]; then continue; fi
  # never copy the installed copy over itself — that would rm -rf the only converter
  if [ "$(sf_realpath "$cand")" = "$MPXJ_DEST_REAL" ]; then continue; fi
  MPXJ_SRC="$cand"
  break
done
# Stage the local source COMPLETELY before the destination is touched — the same
# never-delete-what-you-cannot-replace rule the download path already follows. The self-copy
# skip above is a detection, and a detection has to be correct on every platform and shell to
# be safe; this one was not (it compared logical paths, so a symlink slipped through and the
# copy destroyed the converter). Staging makes a MISSED self-copy harmless instead of fatal, so
# the two defences are independent. `$MPXJ_SRC/.` copies the CONTENTS, so a symlinked source is
# dereferenced into a real directory rather than staged as a link that breaks moments later.
MPXJ_STAGED=0
if [ -n "$MPXJ_SRC" ]; then
  mkdir -p "$INSTALL_ROOT/tools"
  MPXJ_TMP="$INSTALL_ROOT/tools/.mpxj-staging"
  rm -rf "$MPXJ_TMP"
  mkdir -p "$MPXJ_TMP"
  if cp -R "$MPXJ_SRC/." "$MPXJ_TMP/" 2>/dev/null &&
     [ -f "$MPXJ_TMP/classes/MpxjToMspdi.class" ]; then
    MPXJ_STAGED=1
  else
    rm -rf "$MPXJ_TMP"
    warn "MPXJ source at $MPXJ_SRC could not be read — any existing converter is left alone"
  fi
fi
if [ "$MPXJ_STAGED" = "1" ]; then
  rm -rf "$MPXJ_DEST"          # only now, with a complete verified copy already in hand
  mv "$MPXJ_TMP" "$MPXJ_DEST"
  ok "MPXJ converter deployed (native .mpp import enabled)"
elif [ -f "$MPXJ_DEST/classes/MpxjToMspdi.class" ]; then
  # already deployed by an earlier install — keep it, and say what is TRUE (never re-download
  # over a working converter: that is the "nothing already present is reinstalled" rule)
  ok "MPXJ converter already installed — native .mpp import stays ON (existing copy kept)"
elif [ "${SF_MPXJ_OFFLINE:-0}" != "1" ]; then
  echo "    Downloading the MPXJ converter (~17 MB, one time) for native .mpp import..."
  MPXJ_TMP="$INSTALL_ROOT/tools/.mpxj-incoming"
  rm -rf "$MPXJ_TMP"
  mkdir -p "$MPXJ_TMP"
  if (
    printf '%s\n' "$MPXJ_MANIFEST" | while read -r sha rel; do
      [ -n "$rel" ] || continue
      mkdir -p "$MPXJ_TMP/$(dirname "$rel")"
      sf_fetch_mpxj "$rel" "$MPXJ_TMP/$rel" || exit 1
      [ "$(sf_sha256 "$MPXJ_TMP/$rel")" = "$sha" ] || { echo "checksum mismatch: $rel" >&2; exit 1; }
    done
  ) && [ -f "$MPXJ_TMP/classes/MpxjToMspdi.class" ]; then
    rm -rf "$MPXJ_DEST"          # only now, with a fully verified replacement in hand
    mv "$MPXJ_TMP" "$MPXJ_DEST"
    ok "MPXJ converter downloaded and SHA-256 verified (native .mpp import enabled)"
  else
    rm -rf "$MPXJ_TMP"           # destination untouched — an existing install survives
    warn "MPXJ download failed — native .mpp import is OFF"
    warn "  offline? download the repository ZIP (green 'Code' button -> Download ZIP),"
    warn "  extract it, then re-run this installer from inside the extracted folder"
    warn "  until then: export MSPDI XML from MS Project (File > Save As > XML) instead"
  fi
else
  warn "no MPXJ converter found — native .mpp import is OFF"
  warn "  to turn it on: set SF_MPXJ_HOME to an MPXJ folder, or download the repository ZIP"
  warn "  (green 'Code' button -> Download ZIP), extract it, and re-run from inside it"
  warn "  until then: export MSPDI XML from MS Project (File > Save As > XML) instead"
fi

# --- 4. Ollama + this tier's local AI model -------------------------------------------
step "Local AI ($OLLAMA_MODEL) — the tool runs fully without it (skippable)"
if [ "$SMOKE" = "1" ]; then
  warn "Smoke mode: skipping AI install"
else
  read -r -p "    Install Ollama + pull '$OLLAMA_MODEL' (~${MODEL_DISK_GB} GB download)? [Y/n] " ans || ans="n"
  if [[ ! "$ans" =~ ^[Nn] ]]; then
    # ADR-0299: this step is OPTIONAL ("the tool runs fully without it"), so neither half may
    # abort the install. Under `set -euo pipefail` a failed `ollama pull` used to kill the
    # script here — before the launchers, uninstaller and README were written — leaving the
    # operator a venv with no way to start the tool. Every branch now reports honestly and
    # continues (the ADR-0192 rule: never a false [ok], never a silent abort).
    if ! command -v ollama >/dev/null 2>&1; then
      if curl -fsSL https://ollama.com/install.sh | sh; then
        ok "Ollama installed"
      else
        warn "Ollama install failed — skipping the AI model; the tool runs fully without it"
      fi
    else
      ok "Ollama already present"
    fi
    if command -v ollama >/dev/null 2>&1; then
      echo "    Pulling $OLLAMA_MODEL (this is the big download)..."
      if ollama pull "$OLLAMA_MODEL"; then
        ok "Model ready: $OLLAMA_MODEL"
      else
        warn "Model download failed — AI prose stays off until you run: ollama pull $OLLAMA_MODEL"
      fi
    fi
  else
    warn "Skipped — the tool works fully offline; AI prose stays off until a model is installed"
  fi
fi

# --- 5. Start / Stop launchers, desktop entries, uninstaller, README ------------------
step "Creating Start/Stop launchers, uninstaller, and first-run README"
START_SH="$INSTALL_ROOT/start-schedule-forensics.sh"
cat > "$START_SH" <<EOF
#!/usr/bin/env bash
# Polaris² — start (loopback-only; the browser opens automatically).
exec "$VENV_DIR/bin/python" -c "from schedule_forensics.launcher import main; main(port=$APP_PORT)"
EOF
chmod +x "$START_SH"

STOP_SH="$INSTALL_ROOT/stop-schedule-forensics.sh"
cat > "$STOP_SH" <<EOF
#!/usr/bin/env bash
# Polaris² — graceful stop (asks the local app to shut itself down).
if command -v curl >/dev/null 2>&1; then
  curl -fsS -X POST "http://127.0.0.1:$APP_PORT/api/shutdown" >/dev/null 2>&1 \\
    && echo "Polaris² stopped." || echo "Not running (or already stopped)."
else
  "$VENV_DIR/bin/python" - <<'PY'
import urllib.request
try:
    urllib.request.urlopen(urllib.request.Request(
        "http://127.0.0.1:$APP_PORT/api/shutdown", method="POST"), timeout=5)
    print("Polaris² stopped.")
except Exception:
    print("Not running (or already stopped).")
PY
fi
EOF
chmod +x "$STOP_SH"

UNINST="$INSTALL_ROOT/uninstall-schedule-forensics.sh"
cat > "$UNINST" <<EOF
#!/usr/bin/env bash
# Uninstall Polaris² (Schedule Forensics): removes the app folder, launchers, desktop entries.
# Leaves Python / Ollama in place (shared programs); remove the AI model with:
#     ollama rm $OLLAMA_MODEL
"$STOP_SH" || true
rm -f "\$HOME/.local/bin/schedule-forensics-start" "\$HOME/.local/bin/schedule-forensics-stop"
rm -f "\$HOME/.local/share/applications/schedule-forensics-start.desktop" \\
      "\$HOME/.local/share/applications/schedule-forensics-stop.desktop"
rm -rf "$INSTALL_ROOT"
echo "Polaris² removed."
EOF
chmod +x "$UNINST"

cat > "$INSTALL_ROOT/FIRST-RUN-README.txt" <<EOF
Polaris² (Schedule Forensics) — first run
=========================================
Start:  run "Start Polaris²" from your app menu (or $START_SH).
        Your browser opens http://127.0.0.1:$APP_PORT — everything runs ON THIS MACHINE.
Stop:   "Stop Polaris²" (closing the browser also stops it after an idle delay).
Data:   your schedule files NEVER leave this computer (loopback-only by design).
AI:     enable it in AI Settings inside the app (model: $OLLAMA_MODEL).
Remove: $UNINST
EOF

if [ "$SMOKE" != "1" ]; then
  mkdir -p "$HOME/.local/bin" "$HOME/.local/share/applications"
  ln -sf "$START_SH" "$HOME/.local/bin/schedule-forensics-start"
  ln -sf "$STOP_SH"  "$HOME/.local/bin/schedule-forensics-stop"
  cat > "$HOME/.local/share/applications/schedule-forensics-start.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=Start Polaris²
Exec=$START_SH
Terminal=false
Categories=Office;
EOF
  cat > "$HOME/.local/share/applications/schedule-forensics-stop.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=Stop Polaris²
Exec=$STOP_SH
Terminal=false
Categories=Office;
EOF
  ok "Launchers in ~/.local/bin + app-menu entries; uninstaller + README in $INSTALL_ROOT"
else
  ok "Smoke mode: launchers written to $INSTALL_ROOT only (no menu entries)"
fi

echo ""
printf '\033[32mDONE — run "schedule-forensics-start" (or the app-menu entry) to begin.\033[0m\n'
echo "(Everything runs locally at http://127.0.0.1:$APP_PORT — no data leaves this machine.)"
exit 0

# ------------------------------- EMBEDDED PAYLOAD -----------------------------------
# schedule_forensics-1.0.289-py3-none-any.whl (base64, one line per comment; extracted by the awk above)
# ===BEGIN WHEEL_B64===
